import { fileURLToPath } from 'node:url';
import { migrate as migrateNodePg } from 'drizzle-orm/node-postgres/migrator';
import type { NodePgDatabase } from 'drizzle-orm/node-postgres';
import type { Database } from './types.js';

/**
 * SQL migrations generated by `pnpm db:generate` into apps/server/drizzle.
 * Resolves to the same folder from both src/db (dev/test) and dist/db (production).
 */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../../drizzle', import.meta.url));

/**
 * Applies all pending migrations in order inside a transaction. Already-applied
 * migrations (tracked in `drizzle.__drizzle_migrations`) are skipped, so this is
 * safe to run on every deploy.
 */
export async function migrateDatabase(db: Database): Promise<void> {
  // The migrator implementations are identical across pg drivers; node-postgres's
  // only needs the dialect + session that every PgDatabase carries.
  await migrateNodePg(db as unknown as NodePgDatabase<Record<string, never>>, {
    migrationsFolder: MIGRATIONS_FOLDER,
  });
}
